from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(0, 0, 0), 'fixture 1'
assert solve([], 1) == Report(0, 0, 0), 'fixture 2'
assert solve([Entry(8, 3)], 2) == Report(0, 0, 0), 'fixture 3'
assert solve([Entry(6, 3), Entry(7, 5)], 3) == Report(11, 2, 8), 'fixture 4'
assert solve([Entry(11, 1), Entry(0, 6), Entry((-2), 5)], 4) == Report(46, 2, 24), 'fixture 5'
assert solve([Entry(10, 2), Entry(2, 3), Entry(0, 4), Entry(11, 2)], 5) == Report(33, 2, 20), 'fixture 6'
assert solve([Entry(10, 3), Entry(5, 5), Entry(2, 6), Entry(3, 1), Entry(1, 1)], 6) == Report(75, 5, 34), 'fixture 7'
assert solve([Entry(5, 6), Entry((-2), 5), Entry(11, 6), Entry(2, 4), Entry(10, 6), Entry(6, 5)], 7) == Report(192, 6, 37), 'fixture 8'
assert solve([Entry(5, 1), Entry(1, 1), Entry((-1), 1), Entry(8, 4), Entry(7, 4), Entry(5, 4), Entry(11, 3)], 8) == Report(108, 7, 27), 'fixture 9'
assert solve([Entry((-3), 3), Entry(7, 4), Entry(7, 1), Entry((-2), 3), Entry((-1), 4), Entry(4, 5), Entry(8, 4), Entry((-2), 6)], 1) == Report(25, 5, 8), 'fixture 10'
assert solve([Entry(10, 2), Entry(11, 2), Entry(2, 2), Entry(1, 2), Entry(1, 5), Entry(4, 2), Entry(2, 1), Entry((-3), 4), Entry(2, 2)], 2) == Report(27, 5, 11), 'fixture 11'
assert solve([Entry(7, 1), Entry((-3), 1), Entry(5, 6), Entry(10, 1), Entry(8, 3), Entry(6, 3), Entry(2, 3), Entry(5, 3), Entry((-1), 2), Entry(1, 2)], 3) == Report(46, 8, 13), 'fixture 12'
assert solve([Entry(5, 3), Entry(3, 6), Entry(11, 1), Entry(8, 6), Entry(4, 2), Entry(1, 1), Entry(3, 2), Entry(5, 6), Entry(6, 5), Entry(9, 5), Entry(7, 2)], 4) == Report(101, 10, 21), 'fixture 13'
assert solve([Entry(3, 2), Entry(7, 2), Entry(4, 6), Entry(6, 3), Entry(11, 3), Entry(0, 5), Entry(2, 2), Entry(10, 3), Entry((-1), 5), Entry((-1), 1), Entry(11, 6), Entry((-3), 4)], 5) == Report(161, 12, 26), 'fixture 14'
assert solve([], 6) == Report(0, 0, 0), 'fixture 15'
assert solve([Entry((-1), 5)], 7) == Report(36, 1, 36), 'fixture 16'
assert solve([Entry(4, 1), Entry(8, 4)], 8) == Report(28, 2, 24), 'fixture 17'
assert solve([Entry(7, 3), Entry((-1), 4), Entry(3, 4)], 1) == Report(6, 2, 5), 'fixture 18'
assert solve([Entry(11, 3), Entry(5, 2), Entry(4, 3), Entry(4, 2)], 2) == Report(2, 1, 2), 'fixture 19'
assert solve([Entry(1, 5), Entry(5, 4), Entry((-3), 3), Entry(5, 5), Entry((-3), 6)], 3) == Report(64, 5, 21), 'fixture 20'
assert solve([Entry(4, 4), Entry(1, 6), Entry(10, 1), Entry((-3), 1), Entry(4, 1), Entry(4, 6)], 4) == Report(62, 4, 23), 'fixture 21'
assert solve([Entry(1, 6), Entry(6, 5), Entry(6, 5), Entry(0, 5), Entry(0, 2), Entry(11, 1), Entry((-1), 4)], 5) == Report(123, 6, 29), 'fixture 22'
assert solve([Entry(6, 1), Entry((-1), 1), Entry((-3), 4), Entry(9, 5), Entry((-1), 2), Entry(2, 2), Entry((-2), 3), Entry((-1), 6)], 6) == Report(135, 7, 37), 'fixture 23'
assert solve([Entry((-5), 3), Entry(0, 3)], 0) == Report(5, 1, 5), 'fixture 24'
assert solve([Entry(6, 3), Entry(5, 3)], 2) == Report(1, 1, 1), 'fixture 25'
assert solve([Entry(5, 3), Entry(8, 2), Entry((-2), 1)], 2) == Report(5, 2, 4), 'fixture 26'
